raw:
{
  "spells": [
    {
      "id": "spell_water_10",
      "theory": "缓流壁以魔力铺展于水面，在二十米内形成一层黏滞水膜，使小股急流减速。水膜依附水体本身，不改变河道形状或水量，故对洪峰无效。树脂提前搓入水中可增强黏性，维持九十秒。",
      "casting": "双手沿水面横向划开，将树脂搓入水膜，指缝间留出细流通道，完成时掌心朝下轻压。",
      "failure": "水膜局部破裂，出现短暂漩涡，急流反而更乱，岸边泥土被冲散，需重新施术。",
      "counters": [
        "向水膜投入砂石，破坏黏滞层，缓流效果立即消失。",
        "用长杆顺水流方向划开水面，可让水膜提前瓦解。"
      ],
      "socialConsequences": "在河谷，乡约见证下的灌溉承诺常以此术辅助，但若未获下游同意便擅自缓流，可能引发争水纠纷。中陆城市公会许可范围内，此术可用于码头防撞，无许可施放则被视为干扰航道。琥珀海岸港务要求缓流作业不得影响货船航速，违者按航运事故追责。",
      "law": {
        "river": "public",
        "city": "public",
        "port": "public"
      },
      "proficiencyEffects": [
        "低熟练度时水膜覆盖不均，缓流效果时断时续。",
        "熟练度达百点后，水膜能稳定覆盖二十米内目标。",
        "三百点后，可控制水膜黏度，适应不同流速。",
        "六百点以上，水膜边缘整齐，对周围水域扰动极小。"
      ]
    },
    {
      "id": "spell_water_11",
      "theory": "冰藏术在封闭储柜内壁形成吸热细纹，将柜内热量导入柜外，使温度下降。木柜隔热差时，细纹需持续工作，耗魔相应增加。树脂用于稳定细纹，防止开裂，持续九十秒。",
      "casting": "以树脂在柜内壁画出螺旋纹，掌心贴住螺旋中心，缓缓注入魔力，直至柜壁泛起白霜。",
      "failure": "螺旋纹断裂，柜内温度骤升，原本冷藏的食材迅速变质，柜壁可能结露湿滑。",
      "counters": [
        "打开柜门使内外空气流通，细纹吸热效果被抵消。",
        "在柜外壁泼热水，破坏内外温差，冰藏失效。"
      ],
      "socialConsequences": "河谷乡约鼓励村民用此术保存种粮，但未经允许对他人储柜施术可能被视为侵占。中陆城市公会许可的冰藏服务需登记，无许可营业则属违规。港口货主依赖此术保鲜，若因施术不当导致货损，港务会追究责任。",
      "law": {
        "river": "public",
        "city": "public",
        "port": "public"
      },
      "proficiencyEffects": [
        "初学时白霜分布不均，柜内温度波动较大。",
        "百点后细纹能均匀覆盖常见木柜内壁。",
        "三百点时可微调吸热速率，适应不同食材。",
        "六百点以上，柜内温度稳定，几乎不损耗树脂。"
      ]
    },
    {
      "id": "spell_water_12",
      "theory": "回潮术将引来的水分散入土壤孔隙，为干旱田垄补湿。魔力只促进水分渗透，不凭空造水，需耕作者提前引水。树脂协助魔力扩散，维持九十秒，作用范围二十米。",
      "casting": "单手抓取湿土，另一手在田垄上轻挥，同时将树脂撒向空中，引导水汽沉入土中。",
      "failure": "水汽凝结成水洼，无法渗入土壤，田垄表面泥泞而深层依旧干燥，需重新翻土。",
      "counters": [
        "在田垄上覆盖干草，阻止水汽接触土壤。",
        "深翻土壤破坏毛细孔隙，使水分无法均匀扩散。"
      ],
      "socialConsequences": "河谷乡约见证下，农户可请人施术补湿，但未经许可引用他人水源则属侵权。中陆城市公会要求此术不得用于盗取公共水渠。港口附近农田若因补湿导致排水不畅，港务会按货损关联追究。",
      "law": {
        "river": "public",
        "city": "public",
        "port": "public"
      },
      "proficiencyEffects": [
        "低熟练度时水汽只湿润表层，深层土壤仍干。",
        "百点后水分能渗透至作物根部常见深度。",
        "三百点时可控制湿度，避免田垄积水。",
        "六百点以上，补湿均匀，几乎不浪费引来的水。"
      ]
    }
  ]
}
